private_rejected_configuration_contrast.patch_text:
--- a/hw/usb/host-libusb.c
+++ b/hw/usb/host-libusb.c
@@ -96,6 +96,8 @@
     /* VM lab only: one budget across host detach/re-enumeration. */
     bool                             test_enum_reset_once;
     bool                             test_enum_reset_used;
+    bool                             test_config_once;
+    bool                             test_config_used;
     bool                             suppress_remote_wake;
     bool                             allow_kernel_driver_detach;
     bool                             allow_host_reset;
@@ -1299,7 +1301,8 @@
     libusb_device *ldev;
     int rc;

-    if (s->test_enum_reset_once && !usb_host_enum_reset_mode_valid(s)) {
+    if ((s->test_enum_reset_once || s->test_config_once) &&
+        !usb_host_enum_reset_mode_valid(s)) {
         error_setg(errp, "enumeration-reset-once requires explicit WS73 port "
                    "and all existing reset/detach opt-outs");
         return;
@@ -1670,8 +1673,19 @@
     trace_usb_host_set_config(s->bus_num, s->addr, config);

     usb_host_release_interfaces(s);
-    if (s->ddesc.bNumConfigurations != 1) {
+    bool force_once = s->test_config_once && !s->test_config_used &&
+                      s->dh && config == 1 && s->ddesc.bNumConfigurations == 1;
+    if (s->ddesc.bNumConfigurations != 1 || force_once) {
+        if (force_once) {
+            s->test_config_used = true;
+            fprintf(stderr, "WS73_TEST_CONFIG_ONCE_BEGIN: bus=%d addr=%d config=%d\n",
+                    s->bus_num, s->addr, config);
+        }
         rc = libusb_set_configuration(s->dh, config);
+        if (force_once) {
+            fprintf(stderr, "WS73_TEST_CONFIG_ONCE_RESULT: bus=%d addr=%d rc=%d\n",
+                    s->bus_num, s->addr, rc);
+        }
         if (rc != 0) {
             usb_host_libusb_error("libusb_set_configuration", rc);
             p->status = USB_RET_STALL;
@@ -2044,6 +2058,8 @@
                      allow_kernel_driver_detach, true),
     DEFINE_PROP_BOOL("host-reset", USBHostDevice,
                      allow_host_reset, true),
+    DEFINE_PROP_BOOL("test-single-configuration-once", USBHostDevice,
+                     test_config_once, false),
     DEFINE_PROP_BOOL("test-enumeration-reset-once", USBHostDevice,
                      test_enum_reset_once, false),
     DEFINE_PROP_BOOL("guest-reset", USBHostDevice,
